import re

def extract_codes_from_text(text):
    if not text:
        return []
    s=str(text)
    codes=[]
    # Contextual patterns
    patterns=[
        r'(?i)(?:promo\s*code|coupon\s*code|discount\s*code|offer\s*code|use\s*code|enter\s*code|apply\s*code)\s*[:\-\s]*([A-Z0-9]{4,})',
        r'(?i)(?:code)\s*[:\-\s]*([A-Z0-9]{4,})\b',
        r'(?i)(?:use\s+your\s+code)\s*[:\-\s]*([A-Z0-9]{4,})',
    ]
    for pat in patterns:
        for m in re.findall(pat, s):
            if m:
                codes.append(m.strip())

    # Fallback: common promo-code-ish tokens (all caps+digits) mentioned near Amazon deals
    # Take tokens 5-12 chars, uppercase alnum, exclude obvious non-codes.
    tokens=re.findall(r'\b[A-Z0-9]{5,12}\b', s)
    exclude={'AMAZON','ORDER','DELIVERY','FREE','GETRICHQUICK','TIMESHARE','DEALS','COUPON','PROMO','DISCOUNT'}
    for tok in tokens:
        if tok in exclude:
            continue
        # Heuristic: if any promotional keywords also appear nearby in text, keep.
        # We'll simply keep tokens when 'code' or 'coupon' words exist in text.
        if re.search(r'(?i)\b(code|coupon|promo|discount|offer)\b', s):
            codes.append(tok)
    # Clean/dedupe preserving order
    seen=set(); out=[]
    for c in codes:
        c2=c.upper() if c else c
        # Validate: contains at least one letter and one digit
        if not re.search(r'[A-Z]', c2):
            continue
        if not re.search(r'\d', c2):
            continue
        if c2 not in seen:
            seen.add(c2); out.append(c2)
    return out

